njs_inline void
njs_property_query_init(njs_property_query_t *pq, njs_prop_query_t query,
    uint32_t hash, uint8_t own)
{
        pq->query = query;
        pq->lhq.key_hash = hash;
        pq->own = own;

        if (query == NJS_PROPERTY_QUERY_SET) {
            pq->lhq.value = NULL;
            pq->own_whiteout = NULL;
            pq->temp = 0;
        }
}


