void
njs_chb_append0(njs_chb_t *chain, const char *msg, size_t len)
{
    u_char  *p;

    if (len != 0 && !chain->error) {
        p = njs_chb_reserve(chain, len);
        if (njs_slow_path(p == NULL)) {
            return;
        }

